"""A minimal single agent (tools, memory, step limit) and a small orchestrator with worker agents."""
import re

SEARCH = {"population of France": "about 68 million (2024 estimate)"}
def search(q): return SEARCH.get(q, "no result")
def calculator(expr):
    if not re.fullmatch(r"[0-9.+\-*/() ]+", expr): raise ValueError("unsafe expression")
    return eval(expr)
TOOLS = {"search": search, "calculator": calculator}

def policy(question, memory):
    """Stand-in for the LLM: decides the next action from the question and what it has seen so far."""
    if not memory: return ("search", "population of France", "I need the current population first.")
    if len(memory) == 1: return ("calculator", "68 * 2", "Double it.")
    return ("finish", f"About {memory[-1][2]} million.", "I have what I need.")

def run_agent(question, max_steps=5):
    memory = []                                          # short-term memory: (tool, input, observation)
    for step in range(1, max_steps + 1):
        tool, arg, thought = policy(question, memory)
        print(f"step {step} | Thought: {thought}")
        if tool == "finish":
            print(f"        | Final answer: {arg}"); return arg
        obs = TOOLS[tool](arg)
        print(f"        | Action: {tool}[{arg}] -> Observation: {obs}")
        memory.append((tool, arg, obs))
    print("stopped: step limit reached"); return None
run_agent("What is double the population of France?")

# Orchestrator-worker pattern: a planner splits the task, specialised workers handle parts, a critic checks
def planner(task): return ["research key facts", "draft a 2-sentence summary", "check the draft against the facts"]
workers = {
    "research key facts": lambda ctx: "France ~68M people; capital Paris",
    "draft a 2-sentence summary": lambda ctx: f"France has about 68 million people. Its capital is Paris.",
    "check the draft against the facts": lambda ctx: "OK: both claims supported" if "68" in ctx[-1] and "Paris" in ctx[-1] else "REVISE"}
ctx = []
for sub in planner("Brief me on France"):
    out = workers[sub](ctx); ctx.append(out)
    print(f"[orchestrator] {sub:35s} -> {out}")
